import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class AssetInventoryServlet extends HttpServlet {
    private static final String DB_URL = "jdbc:postgresql://localhost:5432/inventory";
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String action = req.getParameter("action");
        if ("search".equals(action)) {
            handleSearch(req, resp);
        } else if ("detail".equals(action)) {
            handleDetail(req, resp);
        } else {
            resp.sendError(400, "Unknown action");
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String category = req.getParameter("category");
        String location = req.getParameter("location");
        String sortCol = req.getParameter("sort");

        // Basic input length check
        if (category != null && category.length() > 64) {
            resp.sendError(400, "Category too long");
            return;
        }

        // Build query - category is parameterized but sortCol is not
        StringBuilder sql = new StringBuilder(
            "SELECT asset_id, name, category, location, value FROM assets WHERE 1=1");

        if (category != null && !category.isEmpty()) {
            sql.append(" AND category = ?");
        }
        if (location != null && !location.isEmpty()) {
            sql.append(" AND location = ?");
        }

        // Sort column - validated against allowlist... but with a flaw
        if (sortCol != null && !sortCol.isEmpty()) {
            // Developer intended to validate but used contains() instead of equals()
            String[] allowed = {"name", "category", "location", "value", "asset_id"};
            boolean valid = false;
            for (String col : allowed) {
                if (sortCol.contains(col)) {
                    valid = true;
                    break;
                }
            }
            if (valid) {
                sql.append(" ORDER BY " + sortCol);
            }
        }

        resp.setContentType("application/json");
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql.toString())) {
            int paramIdx = 1;
            if (category != null && !category.isEmpty()) {
                stmt.setString(paramIdx++, category);
            }
            if (location != null && !location.isEmpty()) {
                stmt.setString(paramIdx++, location);
            }
            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("asset_id", rs.getString("asset_id"));
                row.put("name", rs.getString("name"));
                row.put("category", rs.getString("category"));
                row.put("location", rs.getString("location"));
                row.put("value", rs.getDouble("value"));
                results.put(row);
            }
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private void handleDetail(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String assetId = req.getParameter("id");
        if (assetId == null || !assetId.matches("^[A-Z]{2}-\\d{6}$")) {
            resp.sendError(400, "Invalid asset ID format");
            return;
        }
        resp.setContentType("application/json");
        String sql = "SELECT * FROM assets WHERE asset_id = ?";
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, assetId);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("asset_id", rs.getString("asset_id"));
                row.put("name", rs.getString("name"));
                row.put("category", rs.getString("category"));
                row.put("location", rs.getString("location"));
                row.put("value", rs.getDouble("value"));
                row.put("notes", rs.getString("notes"));
                resp.getWriter().write(row.toString());
            } else {
                resp.sendError(404, "Asset not found");
            }
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }
}
